-- Unpaid requests remain private until processor authorization succeeds.
create or replace function public.create_marketplace_job_v2(p_property_id uuid,p_title text,p_instructions text default null,p_priority public.job_priority default 'standard',p_scheduled_for timestamptz default null,p_duration_minutes integer default 60,p_service_type text default 'unarmed_patrol',p_requested_start text default 'scheduled',p_client_contact_phone text default null,p_access_notes text default null,p_vacation_start_date date default null,p_vacation_end_date date default null,p_vacation_checks_per_day integer default null) returns uuid language plpgsql security definer set search_path='public' set row_security='off' as $$ declare v_client_id uuid; v_job_id uuid; v_est jsonb; v_risk text; begin if auth.uid() is null then raise exception 'Your session has expired. Sign in again.' using errcode='28000'; end if; select c.id,c.risk_level into v_client_id,v_risk from public.clients c join public.profiles p on p.id=c.user_id where c.user_id=auth.uid() and p.role='client' and p.account_status='approved' limit 1; if v_client_id is null then raise exception 'Your approved Client workspace could not be resolved.' using errcode='42501'; end if; if not exists(select 1 from public.properties p where p.id=p_property_id and p.client_id=v_client_id and p.archived_at is null) then raise exception 'Select an active property owned by your Client account.' using errcode='23514'; end if; if nullif(btrim(p_title),'') is null then raise exception 'Mission title is required.' using errcode='23514'; end if; v_est:=public.calculate_job_estimate(p_service_type,p_priority,p_duration_minutes,p_scheduled_for,p_requested_start,p_vacation_start_date,p_vacation_end_date,p_vacation_checks_per_day); insert into public.marketplace_jobs(client_id,property_id,title,instructions,priority,status,scheduled_for,duration_minutes,service_type,requested_start,client_contact_phone,access_notes,estimated_total_cents,platform_fee_cents,agency_payout_cents,pricing_snapshot,payment_status,payout_status,payout_hold_reason,client_risk_level,payout_cents,vacation_start_date,vacation_end_date,vacation_checks_per_day,vacation_total_visits) values(v_client_id,p_property_id,btrim(p_title),nullif(btrim(p_instructions),''),'standard','open',p_scheduled_for,(v_est->>'duration_minutes')::int,v_est->>'service_type',p_requested_start,nullif(btrim(p_client_contact_phone),''),nullif(btrim(p_access_notes),''),(v_est->>'total_cents')::int,(v_est->>'platform_fee_cents')::int,(v_est->>'agency_payout_cents')::int,v_est,'estimate_only','held_until_report','payment_authorization_pending',v_risk,(v_est->>'agency_payout_cents')::int,p_vacation_start_date,p_vacation_end_date,p_vacation_checks_per_day,nullif(v_est->>'vacation_total_visits','')::int) returning id into v_job_id; insert into public.job_financials(job_id,client_id,service_type,duration_minutes,subtotal_cents,priority_surcharge_cents,after_hours_surcharge_cents,total_cents,platform_fee_cents,agency_payout_cents,payment_status,payout_status,hold_reason,vacation_total_visits) values(v_job_id,v_client_id,v_est->>'service_type',(v_est->>'duration_minutes')::int,(v_est->>'subtotal_cents')::int,0,0,(v_est->>'total_cents')::int,(v_est->>'platform_fee_cents')::int,(v_est->>'agency_payout_cents')::int,'estimate_only','held_until_report','payment_authorization_pending',nullif(v_est->>'vacation_total_visits','')::int); insert into public.mission_events(job_id,actor_user_id,event_type,payload) values(v_job_id,auth.uid(),'client_submitted',jsonb_build_object('status','open','property_id',p_property_id,'service_type',v_est->>'service_type','requested_start',p_requested_start,'pricing',v_est)); perform public.notify_role('platform_admin',v_job_id,'client_request_submitted','Client submitted request',btrim(p_title)||' entered the marketplace.','normal'); return v_job_id; end $$;
